/** 
 * Finds all plugin color resources, matching the "colors-*.properties" pattern and adds them to this resource pack.
 * @param resources the map of key, value color resource pairs
 */
private void initColorPluginResources(Map<String,String> resources){
  Iterator<String> pluginProperties = findResourcePaths("colors", "colors-*.properties");
  while (pluginProperties.hasNext()) {
    try {
      String resourceBundleName = pluginProperties.next();
      ResourceBundle resourceBundle = ResourceBundle.getBundle(resourceBundleName.substring(0, resourceBundleName.indexOf(".properties")));
      initResources(resourceBundle, resources);
    } catch (IndexOutOfBoundsException e) {
      System.err.println("Invalid resource bundle name: " + e.getMessage());
    } catch (NullPointerException e) {
      System.err.println("Null value encountered: " + e.getMessage());
    } catch (MissingResourceException e) {
      System.err.println("Missing resource in bundle: " + e.getMessage());
    } catch (UnsupportedOperationException e) {
      System.err.println("Unsupported operation on resources: " + e.getMessage());
    }
  }
}
